def apply_mission_contracts(curriculum):
    for chapter, fix, practice, boss in zip(curriculum, FIXES, PRACTICE, BOSSES):
        for index, spec in ((2, fix), (3, practice), (4, boss)):
            mission = chapter["tasks"][index]
            mission["prompt"] = {"tr": spec["tr"], "ru": spec["ru"]}
            mission["starter"] = spec["starter"]
            mission["tests"] = spec["tests"]
            mission["expected"] = spec["tests"][0]["expected"]
            mission["input"] = spec["tests"][0]["input"]
            mission["concept_rule"] = spec["rule"]
            mission["concept_criteria"] = RULES[spec["rule"]]
            mission["requires"] = [RULES[spec["rule"]]["tr"]]
            mission["hints"] = {
                "tr": ["Ders örneğindeki C++ yapısını düşün.", "Girdi, işlem ve çıktı arasındaki veri akışını izle.", RULES[spec["rule"]]["tr"] + "."],
                "ru": ["Вспомни конструкцию C++ из урока.", "Проследи путь данных от ввода к вычислению и выводу.", RULES[spec["rule"]]["ru"] + "."],
            }

